from taf.ul.ettf.logger import custom_logger, log
from ta5g_iphy import ta5g_iphy
from taf.ul.ettf.config.globals import IPHY0_LMP_IP


logger = custom_logger('Setups_Iphy')


class Iphy(object):
    def __init__(self, config, logs_directory, yaml_filename=None):
        self.iphy = ta5g_iphy()
        self.logs_directory = logs_directory
        self.config = config
        self.yaml_filename = yaml_filename

    @log('Configuring iphy...', 'Iphy configuration finished', logger)
    def configure(self):
        self.iphy.update_and_put_iphy_xml(input_filepath=self.config,
                                          output_dirpath=self.logs_directory,
                                          remote_host=None,
                                          iphy_lmp_ip=IPHY0_LMP_IP,
                                          yaml_filename=self.yaml_filename)
        self.iphy.reset_wts_and_wait_for_enb_to_reach_configured_state()
        self.iphy.check_radios_availability()
